function sumTo(n) {
  if (n === 0) return 0;
  return n + sumTo(n - 1);
}

function factorial(n) {
  if (n === 0) return 1;
  return n * factorial(n - 1);
}

function power(base, exp) {
  if (exp === 0) return 1;
  return base * power(base, exp - 1);
}

function len(list) {
  if (list.length === 0) return 0;
  return 1 + len(list.slice(1));
}

function sumList(list) {
  if (list.length === 0) return 0;
  return list[0] + sumList(list.slice(1));
}

function folderSize(node) {
  if (node.type === "file") return node.size;
  let total = 0;
  for (const child of node.children) total += folderSize(child);
  return total;
}

function sumDigits(n) {
  if (n < 10) return n;
  return (n % 10) + sumDigits(Math.floor(n / 10));
}

function countFiles(node) {
  if (node.type === "file") return 1;
  let total = 0;
  for (const child of node.children) total += countFiles(child);
  return total;
}

function maxDepth(node) {
  if (node.type === "file") return 0;
  if (node.children.length === 0) return 1;
  return 1 + Math.max(...node.children.map(maxDepth));
}

function nestedSum(list) {
  let total = 0;
  for (const item of list) {
    total += typeof item === "number" ? item : nestedSum(item);
  }
  return total;
}

function largestFile(node) {
  if (node.type === "file") return node.size;
  let best = 0;
  for (const child of node.children) best = Math.max(best, largestFile(child));
  return best;
}
